changeSet.sql:
ALTER TABLE public.retail_location
    ADD COLUMN retailer_type_code character varying(64);
COMMENT ON COLUMN public.retail_location.retailer_type_code IS
    'Pack for this store: GAS_STATION, GAS_STATION_ENT, LIQUOR_STORE, DUNKIN_DONUTS, SEVEN_ELEVEN, RESTAURANT, or CLINIC. A tenant''s packs are the distinct codes on its locations. The organization code is only the default for a new location.';
COMMENT ON TABLE public.retail_location IS
    'Store locations for a retail tenant. One tenant owns 1..N locations. Each location has its own pack.';
